          ),
      ).toThrow(RangeError);
    });

    it("rejects negative overflowCostCents", () => {
      expect(
        () =>
          new WeightBasedShippingCalculator(
            [{ upToGrams: 1000, costCents: 100 }],
            -1,
          ),
      ).toThrow(RangeError);
    });

    it("accepts valid brackets with overflow", () => {
      expect(
        () =>
          new WeightBasedShippingCalculator(
            [
              { upToGrams: 500, costCents: 300 },
              { upToGrams: 1000, costCents: 500 },
            ],
            800,
          ),
      ).not.toThrow();
    });
  });

  describe("computeShippingCents", () => {
    const brackets = [
      { upToGrams: 500, costCents: 300 },
      { upToGrams: 1000, costCents: 500 },
      { upToGrams: 5000, costCents: 1000 },
    ];

    it("returns 0 for empty cart", () => {
      const calc = new WeightBasedShippingCalculator(brackets);
      expect(calc.computeShippingCents([], 5000)).toBe(0);
    });

    it("returns 0 when all products have no weight", () => {
      const calc = new WeightBasedShippingCalculator(brackets);
      const lines = [makeLine("a", 3)]; // no weightGrams
      expect(calc.computeShippingCents(lines, 5000)).toBe(0);
    });

    it("selects first bracket when weight is within it", () => {
      const calc = new WeightBasedShippingCalculator(brackets);
      const lines = [makeLine("a", 1, 300)]; // 300g
      expect(calc.computeShippingCents(lines, 5000)).toBe(300);
    });

    it("selects bracket at exact boundary", () => {
      const calc = new WeightBasedShippingCalculator(brackets);
      const lines = [makeLine("a", 1, 500)]; // exactly 500g
      expect(calc.computeShippingCents(lines, 5000)).toBe(300);
    });

    it("selects next bracket when weight exceeds boundary", () => {
      const calc = new WeightBasedShippingCalculator(brackets);
      const lines = [makeLine("a", 1, 501)]; // 501g => second bracket
      expect(calc.computeShippingCents(lines, 5000)).toBe(500);
    });

    it("selects highest bracket at its boundary", () => {
      const calc = new WeightBasedShippingCalculator(brackets);
      const lines = [makeLine("a", 1, 5000)]; // exactly 5000g
      expect(calc.computeShippingCents(lines, 5000)).toBe(1000);
    });

    it("uses overflow cost when weight exceeds all brackets", () => {
      const calc = new WeightBasedShippingCalculator(brackets, 2000);
      const lines = [makeLine("a", 1, 5001)]; // over 5000g
      expect(calc.computeShippingCents(lines, 5000)).toBe(2000);
    });

    it("falls back to heaviest bracket cost when no overflow specified", () => {
      const calc = new WeightBasedShippingCalculator(brackets);
      const lines = [makeLine("a", 1, 10000)]; // way over
      expect(calc.computeShippingCents(lines, 5000)).toBe(1000);
    });

    it("sorts brackets internally (out-of-order input)", () => {
      const unordered = [
        { upToGrams: 1000, costCents: 500 },
        { upToGrams: 500, costCents: 300 },
      ];
      const calc = new WeightBasedShippingCalculator(unordered);
      const lines = [makeLine("a", 1, 400)]; // 400g
      expect(calc.computeShippingCents(lines, 5000)).toBe(300);
    });

    it("sums weight across multiple lines", () => {
      const calc = new WeightBasedShippingCalculator(brackets);
      const lines = [
        makeLine("a", 2, 200), // 400g
        makeLine("b", 1, 300), // 300g => total 700g
      ];
      expect(calc.computeShippingCents(lines, 5000)).toBe(500);
    });
  });
});

