import { describe, it, expect, vi } from "vitest";
import { Cart } from "../src/cart.ts";
import { InventoryError } from "../src/inventory.ts";
import type { Product } from "../src/product.ts";
import type { DiscountPolicy } from "../src/pricing.ts";
import type { TaxCalculator } from "../src/tax.ts";
import type { ShippingCalculator } from "../src/shipping.ts";
import type { PriceFetcher, InventoryChecker } from "../src/inventory.ts";
import type { AsyncTaxRateProvider } from "../src/tax.ts";

const product = (
  id: string,
  unitPriceCents: number,
  weightGrams?: number,
): Product => ({
  id,
  name: `Product ${id}`,
  unitPriceCents,
  weightGrams,
});

describe("Cart — line management", () => {
  it("starts empty with 0 items", () => {
    const cart = new Cart();
    expect(cart.itemCount).toBe(0);
    expect(cart.snapshot()).toEqual([]);
  });

  it("adds a product", () => {
    const cart = new Cart();
    cart.add(product("a", 1000), 2);
    expect(cart.itemCount).toBe(2);
  });

  it("merges quantity when adding same product again", () => {
    const cart = new Cart();
    cart.add(product("a", 1000), 2);
    cart.add(product("a", 1000), 3);
    expect(cart.itemCount).toBe(5);
    const snap = cart.snapshot();
    expect(snap).toHaveLength(1);
    expect(snap[0]!.quantity).toBe(5);
  });

  it("rejects non-positive quantity on add", () => {
    const cart = new Cart();
    expect(() => cart.add(product("a", 1000), 0)).toThrow(RangeError);
    expect(() => cart.add(product("a", 1000), -1)).toThrow(RangeError);
    expect(() => cart.add(product("a", 1000), 1.5)).toThrow(RangeError);
  });

  it("rejects negative unitPriceCents on add", () => {
    const cart = new Cart();
    expect(() => cart.add(product("a", -1), 1)).toThrow(RangeError);
  });

  it("removes a product and returns true", () => {
    const cart = new Cart();
    cart.add(product("a", 1000), 1);
    expect(cart.remove("a")).toBe(true);
    expect(cart.itemCount).toBe(0);
  });

  it("returns false when removing unknown product", () => {
    const cart = new Cart();
    expect(cart.remove("nonexistent")).toBe(false);
  });

  it("updates quantity of existing product", () => {
    const cart = new Cart();
    cart.add(product("a", 1000), 3);
    cart.updateQuantity("a", 5);
    expect(cart.itemCount).toBe(5);
  });

  it("updateQuantity(0) removes the product", () => {
    const cart = new Cart();
    cart.add(product("a", 1000), 3);
    cart.updateQuantity("a", 0);
    expect(cart.itemCount).toBe(0);
    expect(cart.snapshot()).toEqual([]);
  });

  it("updateQuantity throws for unknown product", () => {
    const cart = new Cart();
    expect(() => cart.updateQuantity("x", 5)).toThrow(
      "Product x is not in the cart",
    );
  });

  it("updateQuantity rejects negative quantity", () => {
    const cart = new Cart();
    cart.add(product("a", 1000), 1);
    expect(() => cart.updateQuantity("a", -1)).toThrow(RangeError);
  });

  it("updateQuantity rejects non-integer quantity", () => {
    const cart = new Cart();
    cart.add(product("a", 1000), 1);
    expect(() => cart.updateQuantity("a", 2.5)).toThrow(RangeError);
  });

  it("clear removes all items", () => {
    const cart = new Cart();
    cart.add(product("a", 1000), 2);
    cart.add(product("b", 2000), 1);
    cart.clear();
    expect(cart.itemCount).toBe(0);
    expect(cart.snapshot()).toEqual([]);
  });

  it("snapshot returns a deep copy (mutations do not affect cart)", () => {
    const cart = new Cart();
    cart.add(product("a", 1000), 2);
    const snap = cart.snapshot();
    snap[0]!.quantity = 999;
    snap[0]!.product.unitPriceCents = 1;
    expect(cart.snapshot()[0]!.quantity).toBe(2);
    expect(cart.snapshot()[0]!.product.unitPriceCents).toBe(1000);
  });
});

describe("Cart — pricing pipeline (totals)", () => {
  it("computes subtotal as sum of unitPriceCents * quantity", () => {
    const cart = new Cart();
    cart.add(product("a", 1000), 2);
    cart.add(product("b", 500), 3);
    const totals = cart.totals();
    // 1000*2 + 500*3 = 3500
    expect(totals.subtotalCents).toBe(3500);
  });

  it("empty cart produces all-zero totals", () => {
    const cart = new Cart();
    const totals = cart.totals();
    expect(totals).toEqual({
      subtotalCents: 0,
      discountCents: 0,
      taxCents: 0,
      shippingCents: 0,
      totalCents: 0,
    });
  });

  it("applies discount policy and clamps to [0, subtotal]", () => {
    const discountPolicy: DiscountPolicy = {
      computeDiscountCents: vi.fn().mockReturnValue(300),
    };
    const cart = new Cart({ discountPolicy });
    cart.add(product("a", 1000), 1);
    const totals = cart.totals();
    expect(totals.subtotalCents).toBe(1000);
    expect(totals.discountCents).toBe(300);
    expect(totals.totalCents).toBe(700);
  });

  it("clamps discount to subtotal (no negative discounted subtotal)", () => {
    const discountPolicy: DiscountPolicy = {
      computeDiscountCents: vi.fn().mockReturnValue(2000),
    };
    const cart = new Cart({ discountPolicy });
    cart.add(product("a", 500), 1);
    const totals = cart.totals();
    expect(totals.discountCents).toBe(500); // clamped to subtotal
    expect(totals.totalCents).toBe(0);
  });

  it("clamps negative discount to 0", () => {
    const discountPolicy: DiscountPolicy = {
      computeDiscountCents: vi.fn().mockReturnValue(-100),
    };
    const cart = new Cart({ discountPolicy });
    cart.add(product("a", 1000), 1);
    const totals = cart.totals();
    expect(totals.discountCents).toBe(0);
  });

  it("computes tax on discounted subtotal", () => {
    const discountPolicy: DiscountPolicy = {
      computeDiscountCents: vi.fn().mockReturnValue(200),
    };
    const taxCalculator: TaxCalculator = {
      computeTaxCents: vi.fn().mockReturnValue(80),
    };
    const cart = new Cart({ discountPolicy, taxCalculator, region: "US" });
    cart.add(product("a", 1000), 1);
    cart.totals();
    // tax should be calculated on discounted subtotal (1000 - 200 = 800)
    expect(taxCalculator.computeTaxCents).toHaveBeenCalledWith(800, "US");
  });

  it("computes shipping against discounted subtotal", () => {
    const discountPolicy: DiscountPolicy = {
      computeDiscountCents: vi.fn().mockReturnValue(200),
    };
    const shippingCalculator: ShippingCalculator = {
      computeShippingCents: vi.fn().mockReturnValue(500),
    };
    const cart = new Cart({ discountPolicy, shippingCalculator });
    cart.add(product("a", 1000), 1);
    cart.totals();
    expect(shippingCalculator.computeShippingCents).toHaveBeenCalledWith(
      expect.any(Array),
      800, // discounted subtotal
    );
  });

  it("totalCents = discountedSubtotal + tax + shipping", () => {
    const discountPolicy: DiscountPolicy = {
      computeDiscountCents: vi.fn().mockReturnValue(100),
    };
    const taxCalculator: TaxCalculator = {
      computeTaxCents: vi.fn().mockReturnValue(72),
    };
    const shippingCalculator: ShippingCalculator = {
      computeShippingCents: vi.fn().mockReturnValue(500),
    };
    const cart = new Cart({ discountPolicy, taxCalculator, shippingCalculator });
    cart.add(product("a", 1000), 1);
    const totals = cart.totals();
    // subtotal=1000, discount=100, discounted=900, tax=72, shipping=500
    // total = 900 + 72 + 500 = 1472
    expect(totals.totalCents).toBe(1472);
    expect(totals.subtotalCents).toBe(1000);
    expect(totals.discountCents).toBe(100);
    expect(totals.taxCents).toBe(72);
    expect(totals.shippingCents).toBe(500);
  });

  it("clamps negative tax to 0", () => {
    const taxCalculator: TaxCalculator = {
      computeTaxCents: vi.fn().mockReturnValue(-50),
    };
    const cart = new Cart({ taxCalculator });
    cart.add(product("a", 1000), 1);
    expect(cart.totals().taxCents).toBe(0);
  });

  it("clamps negative shipping to 0", () => {
    const shippingCalculator: ShippingCalculator = {
      computeShippingCents: vi.fn().mockReturnValue(-100),
