describe("CompositeDiscountPolicy", () => {
  describe("constructor validation", () => {
    it("rejects empty policy list", () => {
      expect(() => new CompositeDiscountPolicy([])).toThrow(
        "CompositeDiscountPolicy requires at least one policy",
      );
    });
  });

  describe("sum mode", () => {
    it("sums discounts from all child policies against original subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(10), new FixedAmountDiscountPolicy(200)],
        "sum",
      );
      // 10% of 1000 = 100, fixed 200 => sum = 300
      expect(composite.computeDiscountCents(1000)).toBe(300);
    });

    it("can produce discount exceeding subtotal (caller clamps)", () => {
      const composite = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(80), new FixedAmountDiscountPolicy(500)],
        "sum",
      );
      // 80% of 600 = 480, fixed min(500,600) = 500 => sum = 980 > 600
      expect(composite.computeDiscountCents(600)).toBe(980);
    });

    it("returns 0 for zero subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(50), new FixedAmountDiscountPolicy(100)],
        "sum",
      );
      expect(composite.computeDiscountCents(0)).toBe(0);
    });

    it("returns 0 for negative subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(50)],
        "sum",
      );
      expect(composite.computeDiscountCents(-100)).toBe(0);
    });

    it("defaults to sum mode when mode is omitted", () => {
      const composite = new CompositeDiscountPolicy([
        new PercentageDiscountPolicy(10),
        new FixedAmountDiscountPolicy(200),
      ]);
      expect(composite.computeDiscountCents(1000)).toBe(300);
    });

    it("clamps negative child results to 0 before summing", () => {
      const negativeMock = { computeDiscountCents: () => -50 };
      const composite = new CompositeDiscountPolicy(
        [negativeMock, new FixedAmountDiscountPolicy(100)],
        "sum",
      );
      // max(0, -50) + min(100, 1000) = 0 + 100 = 100
      expect(composite.computeDiscountCents(1000)).toBe(100);
    });
  });

  describe("chain mode", () => {
    it("applies discounts sequentially to remaining subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(10), new PercentageDiscountPolicy(10)],
        "chain",
      );
      // 10% of 1000 = 100, then 10% of 900 = 90 => total = 190
      expect(composite.computeDiscountCents(1000)).toBe(190);
    });

    it("order matters in chain mode", () => {
      const composite1 = new CompositeDiscountPolicy(
        [new FixedAmountDiscountPolicy(300), new PercentageDiscountPolicy(50)],
        "chain",
      );
      // fixed 300 off 1000 => remaining 700, then 50% of 700 = 350 => total 650
      expect(composite1.computeDiscountCents(1000)).toBe(650);

      const composite2 = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(50), new FixedAmountDiscountPolicy(300)],
        "chain",
      );
      // 50% of 1000 = 500, remaining 500, fixed min(300,500) = 300 => total 800
      expect(composite2.computeDiscountCents(1000)).toBe(800);
    });

    it("stops accumulating when remaining reaches 0", () => {
      const composite = new CompositeDiscountPolicy(
        [
          new FixedAmountDiscountPolicy(1000),
          new PercentageDiscountPolicy(50),
        ],
        "chain",
      );
      // fixed 1000 off 1000 => remaining 0, 50% of 0 = 0 => total 1000
      expect(composite.computeDiscountCents(1000)).toBe(1000);
    });

    it("returns 0 for zero subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(50)],
        "chain",
      );
      expect(composite.computeDiscountCents(0)).toBe(0);
    });

    it("clamps negative child results to 0 in chain mode", () => {
      const negativeMock = { computeDiscountCents: () => -100 };
      const composite = new CompositeDiscountPolicy(
        [negativeMock, new FixedAmountDiscountPolicy(200)],
        "chain",
      );
      // max(0, -100) => step 0, remaining still 1000, then min(200, 1000) => 200
      expect(composite.computeDiscountCents(1000)).toBe(200);
    });
  });
